INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q2663351', 'Battle of the River Bug', 'The Battle of the River Bug, sometimes known as the Battle of Volyn'', took place on 22–23 July 1018, in Red Ruthenia, near the Bug River and near Volyn'' (Wołyń) Bolesław''s Kiev Expedition in the 1015–1019 Kievan war of succession. Following the death of Vladimir the Great in 1015, his sons Yaroslav and Sviatopolk were at war about who should inherit the throne of Kievan Rus''.', 1018, 7, 22, 1018, 7, 23, 'day', '22 July 1018 – 23 July 1018', 39, 'https://en.wikipedia.org/wiki/Battle_of_the_River_Bug'),
  ('Q1121044', 'Union of Krewo', 'In a strict sense, the Union of Krewo or Act of Krėva (also spelled Union of Krevo, Act of Kreva; Polish: unia w Krewie; Lithuanian: Krėvos sutartis) comprised a set of prenuptial promises made at Kreva Castle on 14 August 1385 by Jogaila, Grand Duke of Lithuania, in regard to his prospective marriage to the underage reigning Queen Jadwiga of Poland. Though very limited in scope, the "Union of Krewo", in historiography, often refers not only to the particular document but to events of 1385–1386 as a whole.', 1385, 8, 14, NULL, NULL, NULL, 'day', '14 August 1385', 65, 'https://en.wikipedia.org/wiki/Union_of_Krewo'),
  ('Q3920896', 'Battle of Ašmena', 'The Battle of Ashmyany or Ašmena (Lithuanian: Ašmenos mūšis) was fought on 8 December 1432 at Ashmyany between the armies of Švitrigaila and Sigismund Kęstutaitis, two pretenders to the throne of the Grand Duchy of Lithuania during the Lithuanian Civil War (1432–1438).', 1432, 12, 8, NULL, NULL, NULL, 'day', '8 December 1432', 37, 'https://en.wikipedia.org/wiki/Battle_of_Ashmyany'),
  ('Q2599844', 'Battle of Kletsk', 'The Battle of Kletsk was fought on 5 August 1506 near Kletsk in present-day Belarus between the Grand Ducal Lithuanian Army under Michael Glinski, Court Marshal of Lithuania, and the army of the Crimean Khanate under Fetih I Giray and Burnaş I Giray, sons of Meñli I Giray, Khan of Crimea. The battle was the most decisive Lithuanian victory over the Tatars in centuries after the Battle of Blue Waters.', 1506, 8, 5, NULL, NULL, NULL, 'day', '5 August 1506', 43, 'https://en.wikipedia.org/wiki/Battle_of_Kletsk'),
  ('Q1207310', 'Battle of Orsha', 'The Battle of Orsha (Belarusian: Bitva pad Voršaj, Polish: Bitwa pod Orszą, Lithuanian: Oršos mūšis), was fought on 8 September 1514, between the allied forces of the Grand Duchy of Lithuania and the Crown of the Kingdom of Poland, under the command of Lithuanian Grand Hetman Konstanty Ostrogski; and the army of the Grand Duchy of Moscow under Konyushy Ivan Chelyadnin and Kniaz Mikhail Bulgakov-Golitsa. The Battle of Orsha was part of a long series of Muscovite–Lithuanian Wars conducted by Muscovite rulers striving to gather all the former Kievan Rus'' lands under their rule.', 1514, 9, 8, NULL, NULL, NULL, 'day', '8 September 1514', 63, 'https://en.wikipedia.org/wiki/Battle_of_Orsha'),
  ('Q7510315', 'Siege of Polotsk', 'The siege of Polotsk was laid in 1518 by forces of the Grand Duchy of Moscow on Polotsk during the Fourth Muscovite–Lithuanian War (1512–1522). The Lithuanians defended the city.', 1518, 7, NULL, NULL, NULL, NULL, 'month', 'July 1518', 39, 'https://en.wikipedia.org/wiki/Siege_of_Polotsk'),
  ('Q2623793', 'Battle of Ula', 'The Battle of the Ula or Battle of Chashniki was fought during the Livonian War on 26 January 1564 between the Grand Duchy of Lithuania and the Tsardom of Russia on the Ula River (tributary of the Daugava River) north of Chashniki in the Vitebsk Region. The Russian troops, unarmed and moving in a loose formation, were taken by complete surprise and defeated, losing their large wagon train.', 1564, 1, 26, NULL, NULL, NULL, 'day', '26 January 1564', 43, 'https://en.wikipedia.org/wiki/Battle_of_the_Ula'),
  ('Q501828', 'Battle of Mazyr', 'The Battle of Mazyr (Belarusian: Бітва пад Мазыром, Ukrainian: Битва під Мозирем, Polish: Bitwa pod Mozyrzem; 8–9 February 1649) was fought between the Polish–Lithuanian Commonwealth against the Zaporozhian Host as a part of the Khmelnytsky Uprising. Near the city of Mazyr in present-day Belarus, the Polish–Lithuanian Commonwealth’s forces under the command of Prince Janusz Radziwiłł, Adam Pawłowicz, Dzienaj Romanowski, Dawid Kiński and Dowgiałło captured the city of Mazyr, attacked and defeated a forces of the Zaporozhian Cossacks under the command of Colonel Mykhenko, who was killed in…', 1649, 2, 8, 1649, 2, 9, 'day', '8 February 1649 – 9 February 1649', 39, 'https://en.wikipedia.org/wiki/Battle_of_Mazyr'),
  ('Q2660862', 'Battle of Loyew', 'The Battle of Loyew (Belarusian: Бітва пад Лоевам, Ukrainian: Битва під Лоєвом, Polish: Bitwa pod Łojowem; 31 July 1649) was fought between the Zaporozhian Host against the Polish–Lithuanian Commonwealth as a part of the Khmelnytsky Uprising. Near the site of the present-day town of Loyew on the Sozh River in Belarus, a forces of the Zaporozhian under the command of Colonels Mykhailo Krychevsky, Stepan Pobodailo and Martyn Nebaba was defeated by the Polish–Lithuanian Commonwealth''s forces under the command of Prince Janusz Radziwiłł and Nobleman Wincenty Korwin Gosiewski.', 1649, 7, 31, NULL, NULL, NULL, 'day', '31 July 1649', 41, 'https://en.wikipedia.org/wiki/Battle_of_Loyew_(1649)'),
  ('Q982754', 'Battle of Loyew', 'The Battle of Loyew (Belarusian: Бітва пад Лоевам, Ukrainian: Битва під Лоєвом, Polish: Bitwa pod Łojowem; 6 July 1651) was fought between the Polish–Lithuanian Commonwealth against the Cossack Hetmanate as a part of the Khmelnytsky Uprising. Near the site of the present-day town of Loyew on the Sozh River in Belarus, the Polish–Lithuanian Commonwealth’s forces under the command of Prince Janusz Radziwiłł and Mirski attacked and defeated a forces of the Zaporozhian Cossacks under the command of Colonels Martyn Nebaba, Stepan Pobodailo and Prokip Shumeyko with Lytvynenko.', 1651, 7, 6, NULL, NULL, NULL, 'day', '6 July 1651', 39, 'https://en.wikipedia.org/wiki/Battle_of_Loyew_(1651)'),
  ('Q2459908', 'Battle of Shepeleviche', 'The Battle of Shepeleviche (Szepielewicze) or Battle of Ciecierzyn on 24 August 1654 was one of the first battles of the Russo-Polish War (1654–67). It ended with a Russian victory.', 1654, 8, 24, 1654, 8, 25, 'day', '24 August 1654 – 25 August 1654', 47, 'https://en.wikipedia.org/wiki/Battle_of_Shepeleviche'),
  ('Q2657186', 'Battle of Shklow', 'The Battle of Shklov (also spelt Shklow, Szkłów, or Shkloŭ) took place on August 12, 1654, and was one of the first battles of the Russo-Polish War (1654–67); it ended indecisively, with both sides claiming victory. A small Polish–Lithuanian force of about 6,000–7,000 under Great Lithuanian Hetman Janusz Radziwiłł surprised a numerically superior Russian force (of 40,000; some estimates speak of 70,000, but they are likely too high) under knyaz Yakov Cherkassky near Shklow (Polish: Szkłów).', 1654, 8, 12, NULL, NULL, NULL, 'day', '12 August 1654', 45, 'https://en.wikipedia.org/wiki/Battle_of_Shklow'),
  ('Q4087389', 'Battle of Myadel', 'The Battle of Myadel took place on February 8, 1659, during the Russo-Polish War of 1654–1667, near the town of Myadzel, in present-day Belarus. The Russian army of Novgorod led by Ivan Khovansky defeated the Polish–Lithuanians led by Mikołaj Judycki and Władysław Wołłowicz.', 1659, 2, 8, NULL, NULL, NULL, 'day', '8 February 1659', 37, 'https://en.wikipedia.org/wiki/Battle_of_Myadel'),
  ('Q2011225', 'Battle of Polonka', 'The Battle of Polonka (Połonka, Palonka) took place near Polonka (Połonka in Polish, Palonka in Belarusian, in modern Belarus) during the Polish-Russian War (1658-1667) on 29 June 1660 between Polish-Lithuanian and Russian forces. Polish-Lithuanian army under Stefan Czarniecki and Paweł Jan Sapieha forced a Russian retreat through a carefully planned Polish hussar ambush and several tactically effective flanking maneuvers.', 1660, 6, 29, NULL, NULL, NULL, 'day', '29 June 1660', 45, 'https://en.wikipedia.org/wiki/Battle_of_Polonka'),
  ('Q4087352', 'Battle of Basya', 'The Battle of the Basya River (Polish: Bitwa nad rzeką Basia) or Battle of Gubarevo (Russian: Битва у Губарево) took place 28 September 1660 near Basya river 40 kilometers from the city of Mogilev during Thirteen Years'' War. Russian army fought against Crown and Lithuanians Armies.', 1660, 9, 24, 1660, 10, 10, 'day', '24 September 1660 – 10 October 1660', 43, 'https://en.wikipedia.org/wiki/Battle_of_the_Basya_River'),
  ('Q4337397', 'Siege of Lyakhavichy', 'The siege of Lyakhavichy or Lachowicze took place from 23 March to 28 June 1660 during the Russo-Polish War (1654–67). Lachowicze was one of the major Grand Duchy of Lithuania strongholds in the disputed region (modern Belarus).', 1660, 3, 23, 1660, 6, 28, 'day', '23 March 1660 – 28 June 1660', 43, 'https://en.wikipedia.org/wiki/Siege_of_Lyakhavichy'),
  ('Q2065680', 'Battle of Kushliki', 'The Battle of Kushliki on 4 November 1661 between a Polish–Lithuanian force and a Russian Tsardom force was one of the battles of the Russo-Polish War (1654–67). A Lithuanian force of about 14,000 under pułkownik Kazimierz Żeromski made a fortified camp on the right bank of Daugava River (near the village of Kushliki (Kuszliki) in Polotsk Voivodeship) and defeated the first assault of Ivan Andreyevich Khovansky on 24 September.', 1661, 11, 4, NULL, NULL, NULL, 'day', '4 November 1661', 41, 'https://en.wikipedia.org/wiki/Battle_of_Kushliki'),
  ('Q445710', 'Battle of Kletsk', 'The Battle of Kletsk took place on 30 April 1706 (Gregorian calendar), in- and outside the city of Kletsk, Belarus during Charles XII''s Polish campaign of 1701–1706, in the Great Northern War. The Swedish forces were led by Carl Gustaf Creutz who defeated a larger Russian–Cossack force under the command of Semjon Nepljujev and Danylo Apostol.', 1706, 4, 30, NULL, NULL, NULL, 'day', '30 April 1706', 34, 'https://en.wikipedia.org/wiki/Battle_of_Kletsk_(1706)'),
  ('Q1153384', 'Battle of Grodno', 'The Battle of Grodno (1706) was a siege in early 1706 during the Great Northern War. Grodno (Hrodna) was a city of the Polish–Lithuanian Commonwealth at this time.', 1706, 4, 10, NULL, NULL, NULL, 'day', '10 April 1706', 45, 'https://en.wikipedia.org/wiki/Battle_of_Grodno_(1706)'),
  ('Q166015', 'Battle of Lesnaya', 'The Battle of Lesnaya was fought on 9 October 1708 during the Swedish invasion of Russia in the Great Northern War. Russia was the sole remaining enemy of Sweden following the dissolution of the anti-Swedish coalition in 1706.', 1708, 9, 28, NULL, NULL, NULL, 'day', '28 September 1708', 65, 'https://en.wikipedia.org/wiki/Battle_of_Lesnaya'),
  ('Q663359', 'Battle of Holowczyn', 'The Battle of Holowczyn (also spelled Holofzin or Golovchin) was fought in July 1708 between the Russian army and the Swedish army, led by Charles XII of Sweden, who was only 26 years of age at the time. Despite difficult natural obstacles and superior enemy artillery, the Swedes were able to achieve surprise and defeat the numerically superior Russian forces, who were separated from each other, had no overall command and could not coordinate their actions, disallowing them an engagement in full force.', 1708, 7, 14, NULL, NULL, NULL, 'day', '14 July 1708', 55, 'https://en.wikipedia.org/wiki/Battle_of_Holowczyn'),
  ('Q16253643', 'Battle of Grodno', 'The Battle of Grodno (1708) was the first battle of the Swedish invasion of Russia on 26 January 1708, during the Great Northern War. Grodno was a city of the Polish–Lithuanian Commonwealth at this time.', 1708, 1, 26, NULL, NULL, NULL, 'day', '26 January 1708', 37, 'https://en.wikipedia.org/wiki/Battle_of_Grodno_(1708)'),
  ('Q2618930', 'Battle of Stołowicze', 'The battle of Stołowicze (the battle of Stolovichi or Stalovichy) was a clash of the War of the Bar Confederation. It took place on the 24 September 1771 and ended with the defeat of Bar Confederates by Russian general Alexander Suvorov.', 1771, 9, 23, NULL, NULL, NULL, 'day', '23 September 1771', 41, 'https://en.wikipedia.org/wiki/Battle_of_Sto%C5%82owicze'),
  ('Q4871742', 'Battle of Mir', 'The Battle of Mir was a battle between Poland–Lithuania and the Russian Empire during the War of 1792. It took place in the town of Mir, now in Belarus, on June 11, 1792.', 1792, 6, 11, NULL, NULL, NULL, 'day', '11 June 1792', 39, 'https://en.wikipedia.org/wiki/Battle_of_Mir_(1792)'),
  ('Q9172826', 'Battle of Brest (1792)', 'The Battle of Brest (Russian: Битва под Брестом; Polish: Bitwa pod Brześciem) was defensive battle of 5,000 Polish-Lithuanian troops tried to cover the way to Warsaw from the Russians. An equally strong Russian detachment was acting against them.', 1792, 7, 23, NULL, NULL, NULL, 'day', '23 July 1792', 37, 'https://en.wikipedia.org/wiki/Battle_of_Brest_(1792)'),
  ('Q9173384', 'Battle of Opsa', 'The Battle of Opsa took place on 26 May 1792, during the Polish-Russian War of 1792. The battle was fought near the tiny village of Opsa, near Brasław, Grand Duchy of Lithuania (present-day Belarus), between the Russian corps of Prince Yuri Dolgorukov and the Tatar regiment of the Grand Duchy, commanded by Michał Kirkor.', 1792, 5, 26, NULL, NULL, NULL, 'day', '26 May 1792', 37, 'https://en.wikipedia.org/wiki/Battle_of_Opsa'),
  ('Q555839', 'Battle of Berezina', 'The Battle of (the) Berezina (or Beresina) took place from 26 to 29 November 1812, between Napoleon''s Grande Armée and the Imperial Russian Army under Field Marshal Wittgenstein and Admiral Chichagov. Napoleon was retreating toward Poland in chaos after the aborted occupation of Moscow and trying to cross the Berezina River at Borisov.', 1812, 11, 26, 1812, 11, 29, 'day', '26 November 1812 – 29 November 1812', 66, 'https://en.wikipedia.org/wiki/Battle_of_Berezina'),
  ('Q738791', 'Battle of Czasniki', 'The Battle of Chashniki (Russian: Бой под Чашниками; Belarusian: Бой пад Чашнікамі; Lithuanian: Čašnikų mūšis), sometimes also called the Battle of Czasniki (from the Polish spelling – Polish: Czaśniki), was fought during Napoleon''s invasion of Russia, on 31 October 1812, between Russian forces under General Wittgenstein, and the French Army, commanded by Marshal Victor. This battle was a failed effort by the French to reestablish their northern "Dvina Line", which had crumbled as a result of Wittgenstein''s victory at the second battle of Polotsk just two weeks earlier.', 1812, 10, 31, NULL, NULL, NULL, 'day', '31 October 1812', 41, 'https://en.wikipedia.org/wiki/Battle_of_Chashniki'),
  ('Q738813', 'Battle of Smoliani', 'At the Battle of Smoliani or Smolyany (N.S. November 13–14, 1812), the Russians under General Peter Wittgenstein defeated the French forces of Marshal Claude Victor and Marshal Nicholas Oudinot. This battle was the last effort of the French to reestablish their northern flank in Russia, known as the "Dvina Line".', 1812, 11, 13, 1812, 11, 14, 'day', '13 November 1812 – 14 November 1812', 41, 'https://en.wikipedia.org/wiki/Battle_of_Smoliani'),
  ('Q743671', 'Battle of Kobrin', 'The Battle of Kobrin, or the Battle of Kobryn, took place on 27 July 1812 between the Russian and Saxon forces – under the command of Alexander Tormasov and Jean Reynier respectively – in the city of Kobrin (Kobryn) at the initial stage of the French invasion of Russia. The battle was a clear victory of the Russian forces.', 1812, 7, 27, NULL, NULL, NULL, 'day', '27 July 1812', 43, 'https://en.wikipedia.org/wiki/Battle_of_Kobrin'),
  ('Q840790', 'Battle of Saltanovka', 'The Battle of Saltanovka, also known as the Battle of Mogilev (French: Bataille de Mogilev), took place on 23 July 1812 during the early stages of the 1812 French invasion of Russia.', 1812, 7, 23, NULL, NULL, NULL, 'day', '23 July 1812', 50, 'https://en.wikipedia.org/wiki/Battle_of_Saltanovka'),
  ('Q903248', 'First Battle of Polotsk', 'In the First Battle of Polotsk, which took place on 17–18 August 1812, Russian troops under the command of Peter Wittgenstein fought French and Bavarian troops led by Nicolas Oudinot near the city of Polotsk, halting Oudinot''s advance toward Saint Petersburg once more as at the Battle of Klyastitsy. It was a strategic Russian success, but tactically the battle ended in a draw.', 1812, 8, 17, 1812, 8, 18, 'day', '17 August 1812 – 18 August 1812', 53, 'https://en.wikipedia.org/wiki/First_Battle_of_Polotsk'),
  ('Q2889345', 'Battle of Mir', 'The Battle of Mir took place on 9 and 10 July 1812 during Napoleon''s invasion of Russia. Three Polish Lancers divisions battled against Russian cavalry, ending in the first major Russian victory in the war.', 1812, 7, 9, 1812, 7, 10, 'day', '9 July 1812 – 10 July 1812', 50, 'https://en.wikipedia.org/wiki/Battle_of_Mir_(1812)'),
  ('Q4872691', 'Battle of Vitebsk', 'The battle of Vitebsk, sometimes spelled Witepsk (Russian: Сражение при реке Лучосе, romanized: Battle of the Luchosa River), was a military engagement that took place on 26 and 27 July 1812 during the French invasion of Russia. The battle put a French force, under the command of Emperor Napoleon I, in combat with Russian rearguard forces under General Pyotr Konovnitsyn (on 26 July) and Peter von der Pahlen (on 27 July) and ended with the Russian forces making a strategic retreat from the battlefield.', 1812, 7, 26, 1812, 7, 27, 'day', '26 July 1812 – 27 July 1812', 37, 'https://en.wikipedia.org/wiki/Battle_of_Vitebsk_(1812)'),
  ('Q4077792', 'Baranovichi Offensive', 'The Baranovichi offensive was a battle fought on the Eastern Front during World War I between an army of Russia and the forces of Germany and Austria-Hungary in July 1916.', 1916, 7, 25, NULL, NULL, NULL, 'day', '25 July 1916', 50, 'https://en.wikipedia.org/wiki/Baranovichi_offensive'),
  ('Q2632595', 'Slutsk Uprising', 'The Slutsk uprising (Belarusian: Слуцкае паўстанне, romanized: Sluckaje paŭstannie) or the Slutsk defence, or Slitsk military action (Belarusian: Слуцкі збройны чын, romanized: Slucki zbrojny čyn) was an unsuccessful armed attempt to establish an independent Belarus. It took place in late 1920, near the end of the Polish-Soviet War, in the region of the town of Slutsk.', 1920, 12, 31, NULL, NULL, NULL, 'day', '31 December 1920', 41, 'https://en.wikipedia.org/wiki/Slutsk_uprising'),
  ('Q694416', 'Battle of Brześć Litewski', 'The Battle of Brześć Litewski (also known as the siege of Brześć, the battle of Brest-Litovsk or simply the battle of Brześć) was a World War II battle involving German and Polish forces that took place between 14 and 17 September 1939, near the town of Brześć Litewski, Poland (now Brest, Belarus). After three days of heavy fights for the stronghold in the town of Brześć, the Germans captured the fortress and the Poles withdrew.', 1939, 9, 14, 1939, 9, 17, 'day', '14 September 1939 – 17 September 1939', 50, 'https://en.wikipedia.org/wiki/Battle_of_Brze%C5%9B%C4%87_Litewski'),
  ('Q2630512', 'Battle of Grodno', 'The Battle of Grodno took place between 20 September and 22 September 1939, during the Soviet invasion of Poland. It was fought between improvised Polish units under General Wacław Przeździecki and Soviet Red Army troops of Komkor Ivan Boldin''s Dzerzhinsky Cavalry Mechanized Group, at the time in a non-aggression agreement with Nazi Germany under the Ribbentrop-Molotov Pact.', 1939, 9, 20, 1939, 9, 24, 'day', '20 September 1939 – 24 September 1939', 43, 'https://en.wikipedia.org/wiki/Battle_of_Grodno_(1939)'),
  ('Q611789', 'Defense of Brest Fortress', 'The defense of Brest Fortress was the first battle of Operation Barbarossa, the Axis invasion of the Soviet Union launched on 22 June 1941. The German Army attacked without warning, expecting to take Brest on the first day, using only infantry and artillery, but it took them a week, and only after two bombardments by the Luftwaffe.', 1941, 6, NULL, 1941, 6, 29, 'month', 'June 1941 – 29 June 1941', 65, 'https://en.wikipedia.org/wiki/Defense_of_Brest_Fortress'),
  ('Q4299200', 'Siege of Mahilow', 'The siege of Mogilev was a three-week encirclement of Mogilev undertaken by German troops, part of the Battle of Smolensk during World War II. After the beginning of Operation Barbarossa, the German invasion of the Soviet Union, German troops broke through Soviet lines. Mogilev was heavily fortified and bypassed by German tank forces.', 1941, 7, 3, 1941, 7, 26, 'day', '3 July 1941 – 26 July 1941', 41, 'https://en.wikipedia.org/wiki/Siege_of_Mogilev'),
  ('Q9212027', 'Chervyen massacre', 'The Chervyen massacre (Lithuanian: Červenės žudynės; Belarusian: Чэрвеньскія расстрэлы, romanized: Červieńskija rasstrely), also called the Minsk–Chervyen Death March (Polish: Droga śmierci Mińsk–Czerwień) was a NKVD prisoner massacre on 25–27 June 1941. Political prisoners from Lithuania, Poland and Belarus were forced by the NKVD into a death march eastwards from Minsk to Chervyen (present-day Belarus) after Operation Barbarossa began and many were executed.', 1941, 6, NULL, NULL, NULL, NULL, 'month', 'June 1941', 41, 'https://en.wikipedia.org/wiki/Chervyen_massacre'),
  ('Q430700', 'Khatyn massacre', 'Khatyn (Belarusian: Хаты́нь, romanized: Khatyń, pronounced [xaˈtɨnʲ]; Russian: Хаты́нь, pronounced [xɐˈtɨnʲ]) was a village of 26 houses and 157 inhabitants in Belarus, in Lahoysk district, Minsk region, 50 km from Minsk. On 22 March 1943, almost its entire population was massacred by the Schutzmannschaft Battalion 118, made up mostly of Ukrainian and other Soviet collaborators, assisted by the SS-Sonderbataillon Dirlewanger, in retaliation for an attack on German troops by Soviet partisans.', 1943, 3, 22, NULL, NULL, NULL, 'day', '22 March 1943', 58, 'https://en.wikipedia.org/wiki/Khatyn_massacre'),
  ('Q2341305', 'Battle of Lenino', 'The Battle of Lenino was a tactical World War II engagement that took place on 12 and 13 October 1943, north of the village of Lenino in the Mogilev region of Byelorussia. The battle itself was a part of a larger Soviet Spas-Demensk offensive operation with the aims of clearing the eastern bank of the Dnieper River of German forces and piercing the Panther-Wotan line of defences.', 1943, NULL, NULL, 1943, 10, 13, 'year', '1943', 51, 'https://en.wikipedia.org/wiki/Battle_of_Lenino'),
  ('Q2574041', 'Polotsk Offensive', 'The Polotsk offensive (Russian: Полоцкая наступательная операция) was part of the second phase of the Belorussian strategic offensive of the Red Army in summer 1944, commonly known as Operation Bagration. The Soviet First Baltic Front successfully pursued the retreating remnants of the German Third Panzer Army back towards Polotsk, which was reached by 1 July.', 1944, 7, 4, 1944, 7, 4, 'day', '4 July 1944', 41, 'https://en.wikipedia.org/wiki/Polotsk_offensive'),
  ('Q15991238', 'Hostages Convention', 'The Hostages Convention (formally the International Convention against the Taking of Hostages) is a United Nations treaty by which states agree to prohibit and punish hostage taking. The treaty includes definitions of "hostage" and "hostage taking" and sets out the principle of aut dedere aut judicare: a party to the treaty must prosecute a hostage taker if no other state requests extradition for prosecution of the same crime.', 1979, 12, 17, NULL, NULL, NULL, 'day', '17 December 1979', 43, 'https://en.wikipedia.org/wiki/Hostages_Convention'),
  ('Q76986', 'Belovezh Accords', 'The Agreement on the creation of the Commonwealth of Independent States (officially), or unofficially the Minsk Agreement and best known as the Belovezha Accords, is the agreement declaring that the Soviet Union (USSR) had effectively ceased to exist and establishing the Commonwealth of Independent States (CIS) in its place as an organization created by the same Union Republics. The documentation was signed at the state dacha near Viskuli in Belovezhskaya Pushcha, Belarus on 8 December 1991, by leaders of three of the four republics (except for the defunct Transcaucasian SFSR) which had…', 1991, 12, 8, NULL, NULL, NULL, 'day', '8 December 1991', 71, 'https://en.wikipedia.org/wiki/Belovezha_Accords'),
  ('Q2618920', '1995 Belarusian referendum', 'A four-question referendum was held in Belarus on 14 May 1995, alongside parliamentary elections. The four issues were the possibility of giving the Russian language equal status with Belarusian, whether new national symbols should be adopted, whether there should be economic integration with Russia and changes to the constitution that would allow early elections if Parliament systematically violated the constitution.', 1995, 5, 14, NULL, NULL, NULL, 'day', '14 May 1995', 58, 'https://en.wikipedia.org/wiki/1995_Belarusian_referendum'),
  ('Q2633441', '1996 Belarusian referendum', 'A seven-question referendum was held in Belarus on 24 November 1996. Four questions were put forward by Alexander Lukashenko, the president of Belarus, on changing the date of the country''s independence day, amending the constitution of Belarus, changing laws on the sale of land and the abolition of the death penalty.', 1996, 11, 24, NULL, NULL, NULL, 'day', '24 November 1996', 48, 'https://en.wikipedia.org/wiki/1996_Belarusian_referendum'),
  ('Q2634583', 'Nyamiha disaster', 'A stampede at the Nyamiha metro station in Minsk, Belarus, on 30 May 1999, killed 53 people, mostly young women.', 1999, 5, 30, NULL, NULL, NULL, 'day', '30 May 1999', 45, 'https://en.wikipedia.org/wiki/Nyamiha_stampede'),
  ('Q2634016', '2004 Belarusian referendum', 'A referendum on allowing President Lukashenko to stand in further elections was held in Belarus on 17 October 2004, alongside parliamentary elections. Lukashenko was nearing the end of his constitutionally-limited two terms, and the change would allow him to run for a third term.', 2004, 10, 17, NULL, NULL, NULL, 'day', '17 October 2004', 50, 'https://en.wikipedia.org/wiki/2004_Belarusian_constitutional_referendum'),
  ('Q2995162', 'Jeans Revolution', 'The Jeans Revolution (Belarusian: Джынсавая рэвалюцыя, transliteration: Džynsavaja revalucyja, Russian: Джинсовая революция, romanized: Dzhinsovaya revolyutsiya) was a term used by Belarus'' democratic opposition to describe its protests following the 2006 Belarusian presidential election.', 2006, 3, 19, 2006, 3, 25, 'day', '19 March 2006 – 25 March 2006', 56, 'https://en.wikipedia.org/wiki/Jeans_Revolution'),
  ('Q6523658', '2010 Belarusian protests', 'The 2010 Belarusian protests were mass protest actions in Belarus against the results of the 2010 Belarusian presidential election, which took place on December 19, 2010 and were brutally dispersed. Between 10,000 and 60,000 people took part in the protest on October Square and Independence Square in Minsk.', 2010, 12, 19, NULL, NULL, NULL, 'day', '19 December 2010', 43, 'https://en.wikipedia.org/wiki/2010_Belarusian_protests'),
  ('Q383549', '2011 Minsk Metro bombing', 'The 2011 Minsk Metro bombing took place on 11 April 2011 when 15 people were killed and 315 were injured when a bomb exploded within the Minsk Metro, Belarus. The explosion happened at the central Kastrychnitskaya station at 17:55 local time.', 2011, 4, 11, NULL, NULL, NULL, 'day', '11 April 2011', 63, 'https://en.wikipedia.org/wiki/2011_Minsk_Metro_bombing'),
  ('Q1189229', '2011 Belarusian protests', 'The 2011 Belarusian protests were a series of peaceful protests by demonstrators in Belarus demanding the resignation of current Belarusian president Alexander Lukashenko, who had been the president of Belarus since 1994. Belarus is an authoritarian state, and in May 2011 presidential candidate Andrei Sannikov was sentenced to five years in prison for taking part in the 2010 presidential election.', 2011, 6, 8, 2011, 10, 12, 'day', '8 June 2011 – 12 October 2011', 47, 'https://en.wikipedia.org/wiki/2011_Belarusian_protests'),
  ('Q18001626', 'Minsk Protocol', 'The Minsk agreements were a series of international agreements which sought to end the Donbas War fought between armed Russian separatist groups, backed by Russian regular forces, and the Armed Forces of Ukraine. By August 2014, Ukraine had re-taken most of the territory seized by separatists.', 2014, 9, 5, NULL, NULL, NULL, 'day', '5 September 2014', 64, 'https://en.wikipedia.org/wiki/Minsk_Protocol'),
  ('Q28842978', '2017 Belarusian protests', 'The 2017 Belarusian protests were a series of demonstrations and street protests against President Alexander Lukashenko that broke out in late February 2017. Protesters mobilized against a tax levied against the unemployed in Belarus.', 2017, 2, 17, 2017, 10, 21, 'day', '17 February 2017 – 21 October 2017', 50, 'https://en.wikipedia.org/wiki/2017_Belarusian_protests'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q97384381', '2020–2021 Belarusian protests', 'The 2020–2021 Belarusian protests were a series of mass political demonstrations and protests against the Belarusian government and President Alexander Lukashenko. The largest anti-government protests in the history of Belarus, the demonstrations began in the lead-up to and during the 2020 presidential election, in which Lukashenko sought his sixth term in office.', 2020, 5, 24, 2021, 3, 25, 'day', '24 May 2020 – 25 March 2021', 74, 'https://en.wikipedia.org/wiki/2020%E2%80%932021_Belarusian_protests'),
  ('Q110999040', 'full-scale Russo-Ukrainian war', 'On 24 February 2022, Russia invaded Ukraine, starting the largest and deadliest war in Europe since World War II, in a major escalation of the existing war between the two countries that began when Russia attacked Ukraine in 2014. The fighting has caused hundreds of thousands of military casualties and tens of thousands of Ukrainian civilian casualties.', 2022, 2, 24, NULL, NULL, NULL, 'day', '24 February 2022', 98, 'https://en.wikipedia.org/wiki/Russo-Ukrainian_war_(2022%E2%80%93present)');
